<script>
(()=>{const p=document.getElementById('product_id'),q=document.getElementById('quantity');if(!p||!q)return;const unit=document.getElementById('unit-price'),qty=document.getElementById('quantity-preview'),total=document.getElementById('sale-total'),hint=document.getElementById('stock-hint');const update=()=>{const o=p.options[p.selectedIndex],price=Number(o?.dataset.price||0),stock=Number(o?.dataset.stock||0),count=Math.max(1,Number(q.value||1));unit.textContent='₱'+price.toFixed(2);qty.textContent=count;total.textContent='₱'+(price*count).toFixed(2);hint.textContent=o?.value?'Available stock: '+stock+' units':'Select a product to check available stock.';hint.className='mt-5 rounded-xl p-3 text-xs '+(count>stock?'bg-rose-500/20 text-rose-200':'bg-white/5 text-slate-300')};p.addEventListener('change',update);q.addEventListener('input',update);update()})();
</script>
